function clientEmailHTML(d) {
  const esc = (v) => String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  return CLIENT_EMAIL_HTML
    .replace(/\{\{name\}\}/g, esc(d.name || 'there'))
    .replace(/\{\{service\}\}/g, esc(d.service || '—'))
    .replace(/\{\{date\}\}/g, esc(d.date || '—'))
    .replace(/\{\{time\}\}/g, esc(d.time || '—'));
}

/** The studio chat receives the digest. No client email is sent or marked sent.
 * Browser calls always query as the caller; only cron or an authenticated operator
 * may use the Worker's staff identity. Never return appointment rows or token URLs. */
async function sendTelegramDigest(env, at = new Date()) {
  const f = env.fetchImpl || fetch,
    date = cairoDay(1, at);
  if (!env.FIREBASE_API_KEY) return { ok: false, date, error: 'no-firebase-key' };
  const token = env.REQ_TOKEN || (await staffToken(env, f));
  if (!token) return { ok: false, date, error: 'staff-login-required' };
  let result = await fetchDay({ ...env, REQ_TOKEN: token }, date, f);
  // A bot isolate may still hold the ID token issued before the owner verified
  // their email. Refresh once. NEVER escalate a dashboard request to bot auth.
  if (
    !env.REQ_TOKEN &&
    ['permission-denied', 'firestore-401'].includes(result.error) &&
    _token.value === token
  ) {
    _token.expires = 0;
    const fresh = await staffToken(env, f);
    if (fresh) result = await fetchDay({ ...env, REQ_TOKEN: fresh }, date, f);
  }
  if (!result.ok) return { ok: false, date, error: result.error };
  const appts = result.appts
    .filter((a) => !/^cancelled$|^canceled$/i.test(a.status))
    .sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
  const chunks = chunkText(formatReminderDigest(appts, date));
  let sent = 0;
  for (const part of chunks) {
    const r = await sendTelegram(part, env, f).catch(() => ({ ok: false, error: 'telegram-unreachable' }));
    if (!r.ok) return { ok: false, date, found: appts.length, sent, parts: chunks.length, error: r.error };
    sent++;
  }
  return { ok: true, date, found: appts.length, sent, parts: chunks.length, telegram: true };
}

/* ───────────────────────── handler ───────────────────────── */

// A short rolling window, independent of the noon digest and of client email.
// The appointment's updateTime acts as an atomic compare-and-set: a reschedule,
// cancellation or overlapping cron prevents claiming the stale version.
function noticeLead(env) {
  const n=Number(env.APPOINTMENT_LEAD_MINUTES ?? 60);
  return Number.isInteger(n) && n>=5 && n<=180 ? n : 60;
}
function noticeWindow(at,lead) {
  const days=new Map();
  // Walk real minutes. Cairo can skip/repeat a civil hour at the DST boundary.
  for(let n=1;n<=lead;n++) {
    const {year,month,day,hour,minute}=cairoParts(+at+n*60000),date=`${year}-${month}-${day}`;
    if(!days.has(date)) days.set(date,new Map());
    const times=days.get(date), t=Number(hour)*60+Number(minute);
    if(!times.has(t)) times.set(t,n);
  }
  return days;
}
async function noticePatch(env,docId,version,marker,f) {
  if(!version) return {error:'missing-document-version'};
  const params=new URLSearchParams({key:env.FIREBASE_API_KEY,'updateMask.fieldPaths':'studioTelegramNotice','currentDocument.updateTime':version});
  const url=`${FS_BASE}/appointments/${encodeURIComponent(docId)}?${params}`;
  const res=await f(url,{method:'PATCH',headers:await fsHeaders(env,f),body:JSON.stringify({fields:{studioTelegramNotice:{mapValue:{fields:Object.fromEntries(Object.entries(marker).map(([k,v])=>[k,{stringValue:v}]))}}}})});
  if(res.ok) { const version=(await res.json()).updateTime;return version?{version}:{error:'missing-document-version'}; }
  const status=(await res.json().catch(()=>({}))).error?.status;
  return res.status===404 || res.status===409 || status==='FAILED_PRECONDITION' ? {conflict:true} : {error:fsCause(res.status)};
}
async function upcomingNotices(env, at, f) {
  const result={sent:0,failed:0};
  if(!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) return {...result,ok:false,error:'telegram-not-configured'};
  const token=await staffToken(env,f);
  if(!token) return {...result,ok:false,error:'staff-login-required'};
  const caller={...env,REQ_TOKEN:token}, window=noticeWindow(at,noticeLead(env));
  for(const [date,times] of window) {
    const day=await fsQuery(caller,{from:[{collectionId:'appointments'}],where:{fieldFilter:{field:{fieldPath:'date'},op:'EQUAL',value:{stringValue:date}}},
      select:{fields:['date','time','name','service','status','showedUp','studioTelegramNotice'].map(fieldPath=>({fieldPath}))}},f);
    if(!day.ok) return {...result,ok:false,error:day.error};
    // Bound outbound subrequests per invocation; remaining slots are eligible
    // again at the next scan. Due-soonest first, without starving on sent rows.
    const due=day.rows.map(doc=>({doc,a:mapAppointment(doc)})).filter(({a})=>a.date===date && a.showedUp==null && /^(confirmed|pending|booked|scheduled)$/i.test(a.status) && /^(?:(?:0?[1-9]|1[0-2]):[0-5]\d\s?[ap]m|(?:[01]?\d|2[0-3]):[0-5]\d)$/i.test(a.time.trim()) && times.has(timeToMinutes(a.time))).sort((x,y)=>times.get(timeToMinutes(x.a.time))-times.get(timeToMinutes(y.a.time)));
    for(const {doc,a} of due) {
      if(result.sent+result.failed>=8) break;
      const minutes=timeToMinutes(a.time),slot=date+'/'+minutes, prior=doc.fields?.studioTelegramNotice?.mapValue?.fields;
      if(fsVal(prior?.slot)===slot && (fsVal(prior?.state)==='sent' || (fsVal(prior?.state)==='sending' && +at-Date.parse(fsVal(prior?.at))<10*60000))) continue;
      const marker={slot,state:'sending',at:at.toISOString()};
      const claim=await noticePatch(caller,a.id,doc.updateTime,marker,f);
      if(claim.conflict) continue;
      if(!claim.version) {result.failed++;result.error=claim.error;continue;}
      const text=`UPCOMING APPOINTMENT · in ${times.get(minutes)} min\n${date} · ${a.time} (Cairo)\n${a.name || 'Studio client'}${a.service?' · '+a.service:''}`;
      const sent=await sendTelegram(text,env,f).catch(()=>({ok:false,error:'telegram-unconfirmed'}));
      if(sent.ok) result.sent++; else {result.failed++;result.error=sent.error;}
      // An uncertain network outcome keeps the lease; don't immediately replay
      // a message Telegram may have accepted. Definitive rejection is retryable.
      if(sent.ok || sent.status && sent.status<500) {
        const done=await noticePatch(caller,a.id,claim.version,{...marker,state:sent.ok?'sent':'retry'},f);
        if(!done.version){result.failed++;result.error=done.error || 'notice-state-changed';}
      }
    }
  }
  return {...result,ok:!result.failed};
}

export default {
  /** Cron Trigger — daily 12:00 Cairo time + 1-min Telegram polling */
  async scheduled(event, env = {}, ctx = {}) {
    const at = new Date(event?.scheduledTime ?? Date.now()),
      { hour, minute, day } = cairoParts(at);
    const noon = hour === '12' && minute === '00',
      f = env.fetchImpl || fetch;
    const work = Promise.all([
      pollTelegram(env, f).catch(() => ({ ok: false, error: 'poll-failed' })),
      noon ? sendTelegramDigest(env, at) : { skipped: true },
      Number(minute)%5===1 ? upcomingNotices(env,new Date(Math.max(+at,Date.now())),f).catch(()=>({ok:false,error:'notice-check-failed'})) : {skipped:true},
      noon && day === '01'
        ? monthlyReport(env, 1, f, at)
            .then((text) => sendReport(text, env, env.TELEGRAM_CHAT_ID, f))
            .catch(() => ({ ok: false }))
        : null,
    ]).then(([bot, digest, upcoming]) => {
      if(!upcoming.skipped && (!upcoming.ok || upcoming.sent)) console[upcoming.ok?'log':'error']('[cron] upcoming appointments',JSON.stringify(upcoming));
      if(!upcoming.skipped && !upcoming.ok) throw new Error('Upcoming appointment: '+upcoming.error);
      if (noon) console[digest.ok ? 'log' : 'error']('[cron] appointment digest', JSON.stringify(digest));
      if (noon && !digest.ok) {
        if (digest.sent) event.noRetry?.(); // never replay the entire digest after a confirmed partial send
        throw new Error('Appointment digest: ' + digest.error);
      }
      return { bot, digest, upcoming };
    });
    if (ctx && ctx.waitUntil) ctx.waitUntil(work);
    return work;

  },

  async fetch(req, env = {}, ctx = {}) {
    const origin = req.headers.get('Origin') || '';
    const url = new URL(req.url);

    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors(origin) });

    /* ── live metal rates ──────────────────────────────────────────────────
       Gold is quoted in USD per troy ounce and the studio bills in EGP, so
       every price on the site depends on this pair. Serving it from the
       Worker rather than the browser means: one server-side fetch instead of
       two (with CORS on a third party we do not control), Cloudflare's edge
       cache absorbing the traffic, and the correct conversion done once, in
       one place. `?refresh=1` bypasses the edge cache. */
    if (url.pathname === '/api/rates') {
      const RATE_CACHE_S = 600;                    /* 10 minutes at the edge */
      const force = url.searchParams.get('refresh') === '1';
      const cache = caches.default;
      const cacheKey = new Request('https://egygriilz.internal/rates/v1', { method: 'GET' });

      if (!force) {
        const hit = await cache.match(cacheKey);
        if (hit) {
          const body = await hit.json().catch(() => null);
          if (body && body.ok) return json(body, 200, { origin });
        }
      }

      const GRAMS_PER_OZT = 31.1034768;
      try {
        const { goldUsdPerOz, usdEgp, egpPerGram24 } = await fetchLiveRates();
        const body = {
          ok: true,
          goldUsdPerOz,
          usdEgp,
          gramsPerOz: GRAMS_PER_OZT,
          egpPerGram24: Math.round(egpPerGram24 * 100) / 100,
          karat: {
            '24': Math.round(egpPerGram24 * 100) / 100,
            '22': Math.round(egpPerGram24 * (22 / 24) * 100) / 100,
            '21': Math.round(egpPerGram24 * (21 / 24) * 100) / 100,
            '18': Math.round(egpPerGram24 * (18 / 24) * 100) / 100,
            '14': Math.round(egpPerGram24 * (14 / 24) * 100) / 100,
            '10': Math.round(egpPerGram24 * (10 / 24) * 100) / 100,
          },
          at: Date.now(),
        };

        const put = new Response(JSON.stringify(body), {
          headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'public, max-age=' + RATE_CACHE_S },
        });
        if (ctx && ctx.waitUntil) ctx.waitUntil(cache.put(cacheKey, put.clone()));
        return json(body, 200, { origin });
      } catch (err) {
        /* The last good copy is still far more useful than an error page. */
        const stale = await cache.match(cacheKey);
        if (stale) {
          const body = await stale.json().catch(() => null);
          if (body && body.ok) {
            return json(Object.assign({}, body, { stale: true, error: String((err && err.message) || err) }), 200, { origin });
          }
        }
        return json({ ok: false, error: String((err && err.message) || err) }, 503, { origin });
      }
    }

    if (url.pathname === '/api/health') {
      return json({
        ok: true,
        orderEmailMode: 'manual-draft',
        studioAppointmentLeadMinutes: noticeLead(env),
        turnstileSiteKey: env.TURNSTILE_SITE_KEY || '',
        channels: {
          telegram: !!(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID),
          ntfy: !!env.NTFY_TOPIC,
          whatsapp_staff: !!(env.WA_TOKEN && env.WA_PHONE_ID && env.WA_TO),
          whatsapp_client: !!(env.WA_TOKEN && env.WA_PHONE_ID && env.WA_BOOKING_TEMPLATE),
          turnstile: !!env.TURNSTILE_SECRET,
          firebase: !!env.FIREBASE_API_KEY,
          staff_login: !!(env.STAFF_EMAIL && env.STAFF_PASSWORD),
        },
        endpoints: {
          health: '/api/health',
          rates: 'GET /api/rates',
          telegram_digest: 'POST /api/remind',
          telegram_bot: 'POST /api/telegram',
          pdf: 'POST /api/pdf',
          studio_read_check: 'GET /api/telegram/check',
          moulds_order: 'POST /api/moulds/order',
          moulds_approve: 'POST /api/moulds/approve',
          moulds_orders: 'GET /api/moulds/orders',
          moulds_status: 'POST /api/moulds/status',
          notify: 'POST /api/notify',
        },
      }, 200, { origin });
    }

    // ── cron: send tomorrow's reminders (called by Cloudflare Cron Trigger) ──
    /* ── Telegram bot webhook ── */
    if (url.pathname === '/api/telegram') {
      const secret = env.TELEGRAM_WEBHOOK_SECRET || '';
      const given = req.headers.get('X-Telegram-Bot-Api-Secret-Token') || '';
      if (!secret || given !== secret) return json({ ok: false, error: 'unauthorized' }, 401, { origin });
      if (req.method !== 'POST') return json({ ok: true, hint: 'POST here from Telegram' }, 200, { origin });
      let update;
      try { update = await req.json(); } catch { return json({ ok: false, error: 'bad-json' }, 400, { origin }); }
      const r = await handleTelegramUpdate(update, env, env.fetchImpl || fetch).catch(e => ({ ok: false, error: String(e) }));
      return json({ ok: true, ...r }, 200, { origin });
    }

    /* ── register the webhook (call once after deploying) ── */
    if (url.pathname === '/api/telegram/setup') {
      const secret = env.CRON_SECRET || '';
      const given = req.headers.get('X-Cron-Key') || '';
      if(req.method!=='POST') return json({ok:false,error:'use-post'},405,{origin});
      if (!secret || given !== secret) return json({ ok: false, error: 'unauthorized' }, 401, { origin });
      if(!env.TELEGRAM_WEBHOOK_SECRET)return json({ok:false,error:'webhook-secret-required'},503,{origin});
      const host = url.host;
      const f = env.fetchImpl || fetch;
      await clearWebhook(env, f).catch(() => {});
      const hook = `https://${host}/api/telegram`;
      const r = await f(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/setWebhook`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          url: hook,
          secret_token: env.TELEGRAM_WEBHOOK_SECRET || undefined,
          allowed_updates: ['message', 'edited_message', 'callback_query'],
        }),
      });
      const d = await r.json().catch(() => ({}));
      return json({ ok: !!d.ok, webhook: hook, telegram: d.description || d.ok }, 200, { origin });
    }

    const orderMail = /^\/api\/orders\/(EGZ-[0-9]{6}-[A-F0-9]{12})\/email$/.exec(url.pathname);
    // Stale tabs must not send anything, even if old mail credentials still exist.
    if (orderMail) return json({ ok: false, error: 'manual-draft-only' }, 410, { origin });

    if (url.pathname === '/api/remind') {
      if (req.method !== 'POST') return json({ ok: false, error: 'use-post' }, 405, { origin });
      if (!originAllowed(origin, env)) return json({ ok: false, error: 'bad-origin' }, 403, { origin });
      const caller = envAsCaller(env, req);
      const operator = !!env.CRON_SECRET && req.headers.get('X-Cron-Key') === env.CRON_SECRET;
      if (!caller.REQ_TOKEN && !operator) return json({ ok: false, error: 'unauthorized' }, 401, { origin });
      const result = await sendTelegramDigest(caller);
      const status = result.ok
        ? 200
        : result.error === 'permission-denied'
          ? 403
          : result.error === 'firestore-401'
            ? 401
            : 502;
      return json(result, status, { origin });
    }

    /* GET /api/telegram/check — verify bot access to Firestore */
    if (url.pathname === '/api/telegram/check') {
      if (req.method !== 'GET') return json({ok:false, error:'use-get'}, 405, {origin});
      if (rateLimited('read-check:' + (req.headers.get('CF-Connecting-IP') || 'unknown'), 6, 60_000))
        return json({ok:false, error:'rate-limited'}, 429, {origin});
      if (!env.FIREBASE_API_KEY) {
        return json({ ok:false, step:'key', message:'FIREBASE_API_KEY is not set in Cloudflare.' }, 200, { origin });
      }
      const f = env.fetchImpl || fetch;
      const token = await staffToken(env, f);
      if (!token) return json({ok:false, step:'login', message:fsErrorText('staff-login-required')}, 200, {origin});
      // Probe list access even on an empty database. Return no IDs, records, tokens
      // or upstream error bodies. Do not claim Telegram delivery was tested.
      const collections = ['appointments', 'order_sheets', 'quotes'];
      for (const col of collections) {
        const r = await fsQuery({...env, REQ_TOKEN:token}, {
          from:[{collectionId:col}], select:projection(['__name__']), limit:1,
        }, f);
        if (!r.ok) return json({ok:false, step:'read', collection:col, error:r.error, message:fsErrorText(r.error)}, 200, {origin});
      }
      return json({ok:true, step:'ready', collections, message:'Private studio reads passed. Telegram and email delivery were not tested.'}, 200, {origin});
    }


    /* POST /api/pdf — Quotes Studio forwards PDF directly to Telegram (multipart, not stored) */
    if (url.pathname === '/api/pdf') {
      if (req.method !== 'POST') return json({ ok: false, error: 'use-post' }, 200, { origin });
      const key = env.PDF_KEY || '';
      if (!key) return json({ ok: false, error: 'PDF_KEY-not-set' }, 503, { origin });
      if (req.headers.get('X-Pdf-Key') !== key) return json({ ok: false, error: 'unauthorized' }, 401, { origin });

      let form;
      try { form = await req.formData(); } catch { return json({ ok: false, error: 'bad-form' }, 400, { origin }); }
      const file = form.get('file');
      if (!file || typeof file === 'string') return json({ ok: false, error: 'no-file' }, 400, { origin });
      if (file.size > 45 * 1024 * 1024) return json({ ok: false, error: 'too-big', limit: '45MB' }, 413, { origin });

      const caption = clean(form.get('caption'), 900);
      const r = await sendPdf(new Uint8Array(await file.arrayBuffer()),
        file.name || 'document.pdf', caption, env, null, env.fetchImpl || fetch);
      return json(r, r.ok ? 200 : 502, { origin });
    }

    /* ── mould kit: a new order from /moulds ──
     * The page posts here first. The Worker signs in as the studio account
     * (STAFF_EMAIL / STAFF_PASSWORD) before writing, so the create passes
     * Firestore's rules — a visitor's browser is anonymous and is refused.
     * The delivery fee is added here too, from settings/site, so the total
     * on the order can never be missing it.
     */
    if (url.pathname === '/api/moulds/order') {
      if (req.method !== 'POST') return json({ ok: false, error: 'use-post' }, 405, { origin });
      if (!originAllowed(origin, env)) return json({ ok: false, error: 'bad-origin' }, 403, { origin });

      let body;
      try { body = await req.json(); } catch { return json({ ok: false, error: 'bad-json' }, 400, { origin }); }
      const ip = req.headers.get('CF-Connecting-IP') || '';
      const limit = parseInt(env.RATE_LIMIT_PER_10MIN || '10', 10);
      if (rateLimited('mould:' + ip, limit)) return json({ ok: false, error: 'rate-limited' }, 429, { origin });

      const src = body.data || body || {};
      const name = clean(src.name, 80);
      const phone = cleanPhone(src.phone);
      const email = clean(src.email, 120);
      if (!name || !phone) return json({ ok: false, error: 'missing-fields' }, 422, { origin });
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
        return json({ ok: false, error: 'bad-email' }, 422, { origin });
      }

      const archesRaw = clean(src.arches, 20).toLowerCase();
      const arches = archesRaw.includes('both') ? 'both' : archesRaw.includes('lower') ? 'lower' : 'upper';
      const archCount = arches === 'both' ? 2 : 1;
      /* the price always comes from settings/site — never from the browser,
         so the delivery fee can neither be dropped nor edited away */
      const prices = await loadMouldPrices(env, env.fetchImpl || fetch);
      const mouldPrice = prices.perArch * archCount;
      const deliveryFee = Math.max(0, prices.delivery);
      const total = mouldPrice + deliveryFee;

      const nowIso = new Date().toISOString();
      const order = {
        name,
        phone,
        email,
        arches,
        archCount,
        perArch: prices.perArch,
        mouldPrice,
        deliveryFee,
        total,
        currency: 'EGP',
        address: clean(src.address, 300),
        mapLink: clean(src.mapLink, 300),
        location: (src.location && typeof src.location === 'object') ? src.location : null,
        status: 'pending',
        source: 'moulds-page',
        paymentLink: '',
        createdAt: nowIso,
      };

      const f = env.fetchImpl || fetch;
      let id = '';
      let stored = false;
      try {
        const fields = {};
        for (const [k, v] of Object.entries(order)) fields[k] = toFsValue(v);
        const r = await f(`${FS_BASE}/mould_orders?key=${env.FIREBASE_API_KEY}`, {
          method: 'POST',
          headers: await fsHeaders(env, f),
          body: JSON.stringify({ fields }),
        });
        if (r.ok) {
          const doc = await r.json().catch(() => null);
          id = String((doc && doc.name) || '').split('/').pop();
          stored = !!id;
          if (stored) isoCacheClear('moulds:');
        } else {
          const t = await r.text().catch(() => '');
          console.log('[moulds] create refused', r.status, t.slice(0, 200));
        }
      } catch (e) {
        console.log('[moulds] create failed', String(e));
      }

      /* the studio still hears about the order even if the database refused
         it — an order in Telegram can be typed in by hand, a lost one cannot */
      const saved = Object.assign({}, order, { id });
      const text = formatMouldOrder(saved) + (stored
        ? ''
        : '\n\n⚠ Not saved to the database — type this order into /editx by hand.');
      const tg = env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID
        ? await tgCall('sendMessage', {
            chat_id: env.TELEGRAM_CHAT_ID,
            text,
            disable_web_page_preview: false,
            ...(stored ? { reply_markup: mouldKeyboard(saved) } : {}),
          }, env, f).catch(e => ({ ok: false, error: String(e) }))
        : { ok: false, skipped: true };
      const ntfy = await sendNtfy(text, 'New mould kit order', env, f)
        .catch(e => ({ channel: 'ntfy', ok: false, error: String(e) }));
      const staffMail = await sendEmail('New mould kit order — EGYGRILLZ', text, env.ALERT_EMAIL, env, f)
        .catch(e => ({ channel: 'email', ok: false, error: String(e) }));

      /* nothing was written and nobody was told — let the page use its own
         browser write instead of pretending the order went through */
      if (!stored && !(tg.ok || ntfy.ok || staffMail.ok)) {
        return json({ ok: false, error: 'not-saved' }, 502, { origin });
      }

      return json({
        ok: true,
        stored,
        id,
        ref: id ? id.slice(0, 8).toUpperCase() : '',
        name,
        arches,
        archCount,
        perArch: prices.perArch,
        mouldPrice,
        deliveryFee,
        total,
        notified: !!(tg.ok || ntfy.ok || staffMail.ok),
      }, 200, { origin });
    }

    /* ── mould kit: approve — save the link + status only ──
     * Nothing is emailed here. The response carries the Gmail draft URL so
     * /editx and the bot can open the compose window; a human presses Send.
     */
    /* ── mould orders: the list /editx shows ──
     * Firestore refuses anonymous reads of `mould_orders` (the collection holds
     * client phone numbers and addresses). The dashboard therefore asks the
     * Worker, which reads with the studio's own credentials.
     * Protect it with the MOULDS_KEY secret and/or ALLOWED_ORIGINS. */
    if (url.pathname === '/api/moulds/orders') {
      if (req.method !== 'GET') return json({ ok: false, error: 'use-get' }, 405, { origin });
      if (!originAllowed(origin, env)) return json({ ok: false, error: 'bad-origin' }, 403, { origin });
      const key = env.MOULDS_KEY || '';
      const given = req.headers.get('X-Moulds-Key') || url.searchParams.get('key') || '';
      /* A signed-in dashboard may read with its own Firebase ID token instead
         of the MOULDS_KEY — that is what /editx sends. */
      const callerEnv = envAsCaller(env, req);
      const hasCaller = !!callerEnv.REQ_TOKEN;
      if ((!key || given !== key) && !hasCaller) return json({ ok: false, error: 'unauthorized' }, 401, { origin });

      const limit = Math.max(1, Math.min(200, parseInt(url.searchParams.get('limit') || '60', 10) || 60));
      const status = clean(url.searchParams.get('status') || '', 20).toLowerCase();
      const force = url.searchParams.get('force') === '1' || url.searchParams.get('force') === 'true';
      const r = await fetchMouldOrders(callerEnv, { limit, status: status || 'all', force }, env.fetchImpl || fetch)
        .catch(e => ({ ok: false, error: String(e), orders: [] }));
      if (!r.ok) {
        const err = r.error || 'firestore';
        const status = err === 'quota' ? 429 : (err === 'permission-denied' ? 403 : 502);
        return json({ ok: false, error: err, orders: [] }, status, { origin });
      }
      return json({ ok: true, count: r.orders.length, orders: r.orders }, 200, { origin });
    }

    if (url.pathname === '/api/moulds/approve') {
      if (req.method !== 'POST') return json({ ok: false, error: 'use-post' }, 405, { origin });
      if (!originAllowed(origin, env)) return json({ ok: false, error: 'bad-origin' }, 403, { origin });
      const key = env.MOULDS_KEY || '';
      const given = req.headers.get('X-Moulds-Key') || url.searchParams.get('key') || '';
      const callerEnv = envAsCaller(env, req);
      if ((!key || given !== key) && !callerEnv.REQ_TOKEN) return json({ ok: false, error: 'unauthorized' }, 401, { origin });

      let body;
      try { body = await req.json(); } catch { return json({ ok: false, error: 'bad-json' }, 400, { origin }); }
      const id = clean(body.id, 120);
      const paymentLink = clean(body.paymentLink, 500);
      if (!id) return json({ ok: false, error: 'missing-id' }, 422, { origin });

      const r = await approveMouldOrder(callerEnv, id, paymentLink, env.fetchImpl || fetch)
        .catch(e => ({ ok: false, error: String(e) }));
      if (!r.ok) {
        const status = r.error === 'not-found' ? 404
          : (r.error === 'no-payment-link' || r.error === 'bad-payment-link') ? 422 : 502;
        return json(r, status, { origin });
      }
      return json({
        ok: true,
        order: r.order,
        subject: r.subject,
        body: r.body,
        gmailUrl: r.gmailUrl,
      }, 200, { origin });
    }

    /* ── mould kit: mark delivered / back to pending ── */
    if (url.pathname === '/api/moulds/status') {
      if (req.method !== 'POST') return json({ ok: false, error: 'use-post' }, 405, { origin });
      if (!originAllowed(origin, env)) return json({ ok: false, error: 'bad-origin' }, 403, { origin });
      const key = env.MOULDS_KEY || '';
      const given = req.headers.get('X-Moulds-Key') || url.searchParams.get('key') || '';
      const callerEnv = envAsCaller(env, req);
      if ((!key || given !== key) && !callerEnv.REQ_TOKEN) return json({ ok: false, error: 'unauthorized' }, 401, { origin });

      let body;
      try { body = await req.json(); } catch { return json({ ok: false, error: 'bad-json' }, 400, { origin }); }
      const id = clean(body.id, 120);
      const status = clean(body.status, 20).toLowerCase();
      if (!id || !['pending', 'approved', 'delivered'].includes(status)) {
        return json({ ok: false, error: 'bad-request' }, 422, { origin });
      }
      const nowIso = new Date().toISOString();
      const fields = { status, statusUpdatedAt: nowIso };
      if (status === 'delivered') fields.deliveredAt = nowIso;
      const patch = await saveMouldOrder(callerEnv, id, fields, env.fetchImpl || fetch);
      return json({ ok: patch.ok, status, error: patch.ok ? undefined : patch.error }, patch.ok ? 200 : 502, { origin });
    }

    if (url.pathname !== '/api/notify' || req.method !== 'POST') {
      return json({ ok: false, error: 'not-found' }, 404, { origin });
    }

    // ── origin check ──
    // Accept the studio's own domains, GitHub previews and *.pages.dev.
    // A visitor's booking must never be dropped because the domain list
    // was not updated after a move.
    if (!originAllowed(origin, env)) {
      return json({ ok: false, error: 'bad-origin' }, 403, { origin });
    }

    // ── body ──
    let body;
    try { body = await req.json(); } catch { return json({ ok: false, error: 'bad-json' }, 400, { origin }); }

    const ip = req.headers.get('CF-Connecting-IP') || '';
    const limit = parseInt(env.RATE_LIMIT_PER_10MIN || '10', 10);
    if (rateLimited(ip, limit)) return json({ ok: false, error: 'rate-limited' }, 429, { origin });

    /* ── mould kit order → instant Telegram alert with buttons ──
     * The order itself is already saved in Firestore by the page, so this
     * call is only the notification. It must never block the client. */
    if (body.type === 'mould') {
      const src = body.data || {};
      if (src.website) return json({ ok: true, notified: true, channels: [] }, 200, { origin }); // honeypot
      const f = env.fetchImpl || fetch;
      const order = {
        id: clean(src.ref, 60),
        name: clean(src.name, 80),
        phone: cleanPhone(src.phone),
        email: clean(src.email, 120),
        arches: clean(src.arches, 20).toLowerCase().includes('both') ? 'both'
          : clean(src.arches, 20).toLowerCase().includes('lower') ? 'lower' : 'upper',
        archCount: Math.max(1, Math.min(2, Number(src.archCount) || 1)),
        mouldPrice: Math.max(0, Number(src.mouldPrice) || 0),
        deliveryFee: Math.max(0, Number(src.deliveryFee) || 0),
        total: Math.max(0, Number(src.total) || 0),
        address: clean(src.address, 300),
        mapLink: clean(src.mapLink, 300),
        status: 'pending',
        paymentLink: '',
      };
      if (!order.name || !order.phone) {
        return json({ ok: false, error: 'missing-fields' }, 422, { origin });
      }
      const text = formatMouldOrder(order);
      const tg = env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID
        ? await tgCall('sendMessage', {
            chat_id: env.TELEGRAM_CHAT_ID,
            text,
            disable_web_page_preview: false,
            reply_markup: mouldKeyboard(order),
          }, env, f).catch(e => ({ ok: false, error: String(e) }))
        : { ok: false, skipped: true };
      const ntfy = await sendNtfy(text, 'New mould kit order', env, f)
        .catch(e => ({ channel: 'ntfy', ok: false, error: String(e) }));
      const staffMail = await sendEmail('New mould kit order — EGYGRILLZ', text, env.ALERT_EMAIL, env, f)
        .catch(e => ({ channel: 'email', ok: false, error: String(e) }));
      return json({
        ok: true,
        notified: !!(tg.ok || ntfy.ok || staffMail.ok),
        channels: [
          { c: 'telegram', ok: !!tg.ok },
          { c: 'ntfy', ok: !!ntfy.ok },
          { c: 'email-staff', ok: !!staffMail.ok },
        ],
      }, 200, { origin });
    }

    const ts = await verifyTurnstile(body.turnstile, env.TURNSTILE_SECRET, ip, env.fetchImpl || fetch);
    if (!ts.ok) return json({ ok: false, error: 'turnstile-failed', detail: ts.reason }, 403, { origin });

    // ── payload ──
    const type = body.type === 'message' ? 'message' : 'booking';
    const src = body.data || {};
    const data = {
      name: clean(src.name, 80),
      phone: cleanPhone(src.phone),
      email: clean(src.email, 120),
      service: clean(src.service, 200),
      date: clean(src.date, 20),
      time: clean(src.time, 20),
      notes: clean(src.notes, 800),
      message: clean(src.message, 1500),
      deposit: clean(src.deposit, 40),
      ref: clean(src.ref, 30),
    };
    // honeypot: bots fill hidden fields
    if (src.website) return json({ ok: true, sent: [] }, 200, { origin }); // silently drop

    if (type === 'booking' && (!data.name || !data.phone || !data.date)) {
      return json({ ok: false, error: 'missing-fields' }, 422, { origin });
    }
    if (type === 'message' && (!data.name || !(data.message || data.phone))) {
      return json({ ok: false, error: 'missing-fields' }, 422, { origin });
    }

    const text = type === 'booking' ? formatBooking(data) : formatMessage(data);
    const title = type === 'booking' ? 'New booking' : 'New message';

    const f = env.fetchImpl || fetch;   // injectable for tests
    const results = await Promise.all([
      sendTelegram(text, env, f).catch(e => ({ channel: 'telegram', ok: false, error: String(e) })),
      sendNtfy(text, title, env, f).catch(e => ({ channel: 'ntfy', ok: false, error: String(e) })),
      sendWhatsApp(text, env, f).catch(e => ({ channel: 'whatsapp', ok: false, error: String(e) })),
      sendWhatsAppToClient(data, type, env, f).catch(e => ({ channel: 'wa-client', ok: false, error: String(e) })),
      sendEmail(`New ${type} — EGYGRILLZ`, text, env.ALERT_EMAIL, env, f)
        .catch(e => ({ channel: 'email-staff', ok: false, error: String(e) })),
      /* Client confirmation email is handled browser-side by EmailJS */
      Promise.resolve({ channel: 'email-client', ok: false, skipped: true }),
    ]);

    const anySent = results.some(r => r.ok);
    // Never fail the visitor's booking because a channel is down.
    return json({ ok: true, notified: anySent, channels: results.map(r => ({ c: r.channel, ok: !!r.ok, skipped: !!r.skipped })) }, 200, { origin });
  },
};

// END EGYGRILLZ DASHBOARD BUNDLE
